import{_ as a,c as i,o as e,ag as s}from"./chunks/framework.B-aGGnuW.js";const k=JSON.parse('{"title":"Partitioning and formatting","description":"","frontmatter":{},"headers":[],"relativePath":"installation/partitioning-formatting.md","filePath":"installation/partitioning-formatting.md","lastUpdated":1792149212000}'),n={name:"installation/partitioning-formatting.md"};function o(r,t,d,p,h,l){return e(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="partitioning-and-formatting" tabindex="-1">Partitioning and formatting <a class="header-anchor" href="#partitioning-and-formatting" aria-label="Permalink to &quot;Partitioning and formatting&quot;">​</a></h1><p>For encryption, follow the <a href="/encryption/">encryption page</a> instead of this page and the mounting page. It returns you to base installation.</p><h2 id="identify-the-disk" tabindex="-1">Identify the disk <a class="header-anchor" href="#identify-the-disk" aria-label="Permalink to &quot;Identify the disk&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lsblk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NAME,SIZE,TYPE,FSTYPE,MOUNTPOINTS,MODEL</span></span></code></pre></div><p>The examples use <code>/dev/nvme0n1</code>, with partitions such as <code>/dev/nvme0n1p1</code>. SATA disks commonly use <code>/dev/sda</code> and <code>/dev/sda1</code>. Substitute your actual devices throughout.</p><div class="danger custom-block"><p class="custom-block-title">Data loss</p><p>Partitioning and formatting can destroy existing data. Check the disk model, size and existing partitions before writing changes. Only format partitions intended for this installation.</p></div><p>Use the interactive terminal partition editor:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cfdisk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/nvme0n1</span></span></code></pre></div><h2 id="uefi-with-gpt" tabindex="-1">UEFI with GPT <a class="header-anchor" href="#uefi-with-gpt" aria-label="Permalink to &quot;UEFI with GPT&quot;">​</a></h2><p>For a new disk, create a GPT partition table and this layout:</p><table tabindex="0"><thead><tr><th>Example partition</th><th>Size</th><th>Type</th><th>Mount point</th></tr></thead><tbody><tr><td><code>/dev/nvme0n1p1</code></td><td>1 GiB</td><td>EFI System</td><td><code>/boot</code></td></tr><tr><td><code>/dev/nvme0n1p2</code></td><td>Remaining space</td><td>Linux filesystem</td><td><code>/</code></td></tr></tbody></table><p>Both bootloaders in this guide use the ESP at <code>/boot</code>, so it holds the kernels and initramfs images too. If reusing an existing ESP, check its free space and <strong>do not format it</strong>. An undersized shared ESP needs a different layout; see <a href="https://wiki.archlinux.org/title/EFI_system_partition" target="_blank" rel="noreferrer">EFI system partition</a>.</p><p>For a new ESP only:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkfs.fat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -F32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EFI</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/nvme0n1p1</span></span></code></pre></div><p>Format the new root partition:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkfs.ext4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ROOT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/nvme0n1p2</span></span></code></pre></div><h2 id="bios" tabindex="-1">BIOS <a class="header-anchor" href="#bios" aria-label="Permalink to &quot;BIOS&quot;">​</a></h2><p>Use GRUB. On a DOS/MBR partition table, create a Linux root partition; there is no ESP. On GPT, also create a 1 MiB <strong>BIOS boot</strong> partition (gdisk type <code>ef02</code>), leaving it unformatted and unmounted. Format only the Linux root partition with ext4, substituting its actual device in the command above.</p><p>See <a href="https://wiki.archlinux.org/title/GRUB#Installation" target="_blank" rel="noreferrer">GRUB installation</a> for firmware-specific requirements.</p><h2 id="optional-home-and-swap-partitions" tabindex="-1">Optional home and swap partitions <a class="header-anchor" href="#optional-home-and-swap-partitions" aria-label="Permalink to &quot;Optional home and swap partitions&quot;">​</a></h2><p>A separate <code>/home</code> partition is optional. If creating one, format it with <code>mkfs.ext4</code> and mount it after root. Do not format an existing home filesystem you intend to keep.</p><p>Swap size depends on workload and whether you need hibernation. You can start without disk swap and configure <a href="/tweaks/#memory-and-swap">zram</a> later. Zram cannot hold a hibernation image. For hibernation, plan disk-backed swap and <a href="https://wiki.archlinux.org/title/Power_management/Suspend_and_hibernate#Hibernation" target="_blank" rel="noreferrer">resume configuration</a> before choosing sizes.</p><p>If you created a swap partition, replace the example device below with that partition:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkswap</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SWAP</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/nvme0n1p3</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swapon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/nvme0n1p3</span></span></code></pre></div>`,24)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
